<?php
/**  * Test Notifications System  * Creates sample notifications to verify the notification system is working  */  require_once __DIR__ . '/backend/lib.php';
require_once __DIR__ . '/public/db_connect.php';
require_login();  $me = current_user();
$user_id = $me['id'];  echo "<!DOCTYPE html><html><head><title>Test Notifications</title>";
echo "<style>body{font-family:Arial;padding:20px;background:#f5f5f5;}";
echo ".success{color:green;padding:10px;background:#d4edda;margin:10px 0;border-radius:5px;}";
echo ".error{color:red;padding:10px;background:#f8d7da;margin:10px 0;border-radius:5px;}";
echo ".info{color:blue;padding:10px;background:#d1ecf1;margin:10px 0;border-radius:5px;}";
echo "button{padding:10px 20px;margin:5px;font-size:14px;cursor:pointer;}";
echo "</style></head><body>";
echo "<h1>Test Notification System</h1>";
echo "<p>Logged in as: <strong>{$me['username']}</strong> (ID: {$user_id})</p>";  try {  // Check if notifications table exists  $check = $pdo->query("SHOW TABLES LIKE 'notifications'")->fetch();  if (!$check) {  echo "<div class='error'>Notifications table does not exist!</div>";  echo "<p>Creating table now...</p>";  $pdo->exec("CREATE TABLE IF NOT EXISTS notifications (  id  INT AUTO_INCREMENT PRIMARY KEY,  user_id  INT NOT NULL,  type  ENUM('success','warning','error','info') NOT NULL DEFAULT 'info',  title  VARCHAR(255) NOT NULL,  message  TEXT NOT NULL,  event_type  VARCHAR(80) NOT NULL DEFAULT 'general',  severity  ENUM('low','medium','high','critical') NOT NULL DEFAULT 'medium',  source_key  VARCHAR(200) NULL,  redirect_url VARCHAR(500) NULL,  status  ENUM('unread','read') NOT NULL DEFAULT 'unread',  created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  read_at  TIMESTAMP NULL,  INDEX idx_user_status (user_id, status),  INDEX idx_created_at  (created_at)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");  echo "<div class='success'> Notifications table created!</div>";  } else {  echo "<div class='success'> Notifications table exists</div>";  }  // Check existing notifications for this user  $stmt = $pdo->prepare("SELECT COUNT(*) FROM notifications WHERE user_id = ?");  $stmt->execute([$user_id]);  $count = $stmt->fetchColumn();  echo "<div class='info'>ℹ You currently have <strong>{$count}</strong> notification(s)</div>";  // Show existing notifications  if ($count > 0) {  echo "<h3>Your Recent Notifications:</h3>";  $stmt = $pdo->prepare("SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC LIMIT 10");  $stmt->execute([$user_id]);  $notifications = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo "<table border='1' cellpadding='8' style='border-collapse:collapse;width:100%;background:white;'>";  echo "<tr style='background:#002F6C;color:white;'>";  echo "<th>ID</th><th>Type</th><th>Title</th><th>Message</th><th>Status</th><th>Created</th></tr>";  foreach ($notifications as $n) {  $statusColor = $n['status'] === 'unread' ? 'orange' : 'green';  echo "<tr>";  echo "<td>{$n['id']}</td>";  echo "<td><span style='background:{$n['type']};color:white;padding:3px 8px;border-radius:3px;font-size:11px;'>{$n['type']}</span></td>";  echo "<td><strong>{$n['title']}</strong></td>";  echo "<td>" . substr($n['message'], 0, 60) . "...</td>";  echo "<td><span style='color:{$statusColor};font-weight:bold;'>{$n['status']}</span></td>";  echo "<td style='font-size:11px;'>{$n['created_at']}</td>";  echo "</tr>";  }  echo "</table>";  }  // Action: Create test notifications  if (isset($_POST['action'])) {  $action = $_POST['action'];  if ($action === 'create_sample') {  $samples = [  [  'type' => 'success',  'title' => 'Transaction Approved',  'message' => 'Your fuel transaction #TXN12345 has been approved by the manager.',  'event_type' => 'transaction',  'severity' => 'low',  'redirect_url' => 'staff_fuel_readings.php'  ],  [  'type' => 'warning',  'title' => 'Low Inventory Alert',  'message' => 'Diesel inventory is running low. Current level: 500 L. Please request delivery.',  'event_type' => 'inventory',  'severity' => 'medium',  'redirect_url' => 'manager_fuel_management_complete.php'  ],  [  'type' => 'info',  'title' => 'Delivery Scheduled',  'message' => 'A fuel delivery is scheduled for tomorrow at 10:00 AM. Total volume: 2000 L.',  'event_type' => 'delivery',  'severity' => 'low',  'redirect_url' => 'manager_fuel_management_complete.php?tab=deliveries'  ],  [  'type' => 'error',  'title' => 'Transaction Rejected',  'message' => 'Fuel reading #TXN12346 was rejected. Reason: Incorrect meter reading. Please re-encode.',  'event_type' => 'transaction',  'severity' => 'high',  'redirect_url' => 'staff_fuel_readings.php'  ],  [  'type' => 'info',  'title' => 'System Update',  'message' => 'The system will undergo maintenance on Saturday 8:00 PM - 10:00 PM.',  'event_type' => 'general',  'severity' => 'medium',  'redirect_url' => '#'  ]  ];  foreach ($samples as $sample) {  $stmt = $pdo->prepare("  INSERT INTO notifications (user_id, type, title, message, event_type, severity, redirect_url, status, created_at)  VALUES (?, ?, ?, ?, ?, ?, ?, 'unread', NOW())  ");  $stmt->execute([  $user_id,  $sample['type'],  $sample['title'],  $sample['message'],  $sample['event_type'],  $sample['severity'],  $sample['redirect_url']  ]);  }  echo "<div class='success'> Created " . count($samples) . " sample notifications!</div>";  echo "<p><a href='test_notifications.php'>Refresh page to see them</a></p>";  }  if ($action === 'mark_all_read') {  $stmt = $pdo->prepare("UPDATE notifications SET status = 'read', read_at = NOW() WHERE user_id = ? AND status = 'unread'");  $stmt->execute([$user_id]);  echo "<div class='success'> All notifications marked as read!</div>";  echo "<p><a href='test_notifications.php'>Refresh page</a></p>";  }  if ($action === 'delete_all') {  $stmt = $pdo->prepare("DELETE FROM notifications WHERE user_id = ?");  $stmt->execute([$user_id]);  echo "<div class='success'> All your notifications deleted!</div>";  echo "<p><a href='test_notifications.php'>Refresh page</a></p>";  }  }  } catch (Exception $e) {  echo "<div class='error'>Error: " . htmlspecialchars($e->getMessage()) . "</div>";  echo "<pre>" . htmlspecialchars($e->getTraceAsString()) . "</pre>";
}  echo "<hr>";
echo "<h3>Actions:</h3>";
echo "<form method='post' style='display:inline;'>";
