echo "<button type='submit' style='background:#28a745;color:white;border:none;'> Create 5 Sample Notifications</button>";
echo "</form>";  echo "<form method='post' style='display:inline;'>";
echo "<input type='hidden' name='action' value='mark_all_read'>";
echo "<button type='submit' style='background:#17a2b8;color:white;border:none;'> Mark All as Read</button>";
echo "</form>";  echo "<form method='post' style='display:inline;'>";
echo "<input type='hidden' name='action' value='delete_all'>";
echo "<button type='submit' style='background:#dc3545;color:white;border:none;' onclick='return confirm(\"Delete all your notifications?\")'>Delete All My Notifications</button>";
echo "</form>";  echo "<hr>";
